S=[]
S.append(E('Six solides à reconnaître','Observe les solides A à F. Les dessins sont des vues de ces objets.\n\n[IMAGE_1]',[
 q('Nomme A et B.','Observe la forme des faces.','A a six faces carrées égales ; B ressemble à une boîte allongée à faces rectangulaires.','A est un cube ; B est un pavé droit.'),q('Nomme C.','Cherche la forme toute ronde.','C n’a ni coin ni face plane ; il ressemble à une balle pleine.','Une boule.'),q('Nomme D.','Repère deux bases rondes de même taille.','D ressemble à une boîte de conserve.','Un cylindre.'),q('Nomme E.','Observe la base ronde et la pointe.','E ressemble à un chapeau de fête.','Un cône.'),q('Nomme F et décris sa base.','Observe les triangles qui se rejoignent en haut.','Quatre faces triangulaires partent des côtés d’une base carrée.','Une pyramide à base carrée.')],{'1':'six_solides.png'}))
S.append(E('Compter sur un cube','Manipule un cube si tu en as un, ou utilise cette vue.\n\n[IMAGE_1]',[
 q('Quelle est la forme d’une face ?','Observe chaque surface plane.','Les faces ont quatre côtés égaux et quatre angles droits.','Un carré.'),q('Combien de faces possède le cube ?','Tourne l’objet ou pense aux faces cachées.','Il y a une face devant, derrière, à gauche, à droite, en haut et en bas.','6 faces.'),q('Combien d’arêtes possède-t-il ?','Compte celles du haut, du bas et celles qui les relient.','$4+4+4=12$.','12 arêtes.'),q('Combien de sommets possède-t-il ?','Compte les coins du haut et du bas.','$4+4=8$.','8 sommets.'),q('Comment évites-tu un double comptage ?','Marque les éléments déjà comptés.','Tu peux poser un petit repère sur chaque face, arête ou sommet déjà compté.','En marquant ce qui a déjà été compté.')],{'1':'cube.png'}))
S.append(E('Compter sur un pavé droit','Manipule un pavé droit, par exemple une boîte rectangulaire.',[
 q('Quelle forme ont ses faces ?','Observe les surfaces planes de la boîte.','Elles sont rectangulaires ; certaines peuvent aussi être carrées.','Des rectangles, parfois des carrés.'),q('Combien de faces a-t-il ?','Compte en tournant la boîte.','Devant, derrière, gauche, droite, dessus et dessous forment six faces.','6 faces.'),q('Combien d’arêtes a-t-il ?','Compte par groupes pour ne rien oublier.','$4+4+4=12$ : quatre en haut, quatre en bas et quatre qui les relient.','12 arêtes.'),q('Combien de sommets a-t-il ?','Repère les coins des deux faces opposées du haut et du bas.','$4+4=8$.','8 sommets.'),q('Quelle différence vois-tu avec un cube ?','Compare les longueurs des arêtes et les formes des faces.','Dans un cube, toutes les faces sont des carrés de même taille ; un pavé allongé n’a pas cette propriété.','Le cube a six faces carrées égales ; le pavé peut avoir des faces rectangulaires de tailles différentes.')]))
S.append(E('Les faces d’une pyramide','Observe une pyramide à base carrée.\n\n[IMAGE_1]',[
 q('Quelle forme a sa base ?','Regarde la face sur laquelle elle peut reposer.','La consigne indique une base carrée.','Un carré.'),q('Combien de côtés a cette base ?','Un carré a quatre côtés.','On peut placer un triangle sur chaque côté de la base.','4 côtés.'),q('Combien de faces triangulaires montent au sommet ?','Compte un triangle par côté de la base.','Les quatre triangles se rejoignent au même sommet.','4 faces triangulaires.'),C('Combien de faces y a-t-il en tout ?','Ajoute la base carrée aux quatre triangles.','1+4',5,'faces'),q('Pourquoi ne faut-il pas compter seulement les triangles ?','La base est elle aussi une face.','Le carré du dessous appartient au solide même s’il est caché.','Parce qu’il faut aussi compter la base carrée.')],{'1':'pyramide.png'}))
S.append(E('Fabriquer le squelette d’un cube','Prépare des tiges de même longueur et de la pâte à modeler pour fabriquer le squelette d’un cube.',[
 q('Que représente chaque tige ?','Une tige suit le bord entre deux faces.','Les tiges correspondent aux arêtes du cube.','Une arête.'),q('Que représente chaque boule de pâte ?','Elle réunit les tiges dans un coin.','Une boule correspond à un sommet.','Un sommet.'),q('Combien de tiges faut-il ?','Compte les arêtes du cube.','$4+4+4=12$.','12 tiges.'),q('Combien de boules faut-il ?','Compte les sommets.','$4+4=8$.','8 boules de pâte.'),q('Combien de tiges se rejoignent à chaque boule ?','Observe un coin du cube.','Trois arêtes partent de chacun de ses sommets.','3 tiges.')]))
S.append(E('Assembler une pyramide','Avec un adulte, prépare les faces de ce modèle : un carré de côté 4 cm et quatre triangles identiques de base 4 cm et de hauteur 4 cm. Le modèle est réduit : reproduis les mesures sur du papier.\n\n[IMAGE_1]',[
 q('Quelle face sert de base ?','Repère le carré central.','Il formera le dessous de la pyramide.','Le carré.'),q('Combien de triangles faut-il préparer ?','Un triangle doit rejoindre chaque côté du carré.','Le carré a quatre côtés.','4 triangles.'),q('Quels bords devront se rejoindre ?','Des bords qui se collent doivent avoir la même longueur.','La base de chaque triangle correspond à un côté de 4 cm du carré ; les côtés libres des triangles se rejoignent deux à deux.','Les bases des triangles avec les côtés du carré, puis les côtés libres des triangles entre eux.'),q('Où se rejoignent les pointes des quatre triangles ?','Relève les quatre faces autour de la base.','Leurs pointes se rencontrent au-dessus du carré.','Au sommet de la pyramide.'),q('Comment vérifies-tu la construction ?','Compare avec le modèle réel ou la vue du solide.','La base reste carrée et les quatre triangles ferment le solide sans trou entre les faces.','Un carré en base et quatre triangles réunis au sommet.')],{'1':'faces_pyramide.png'}))
S.append(E('Des solides dans les objets','On observe une boîte de conserve et une balle pleine.',[
 q('Quel solide ressemble à la boîte de conserve ?','Repère ses deux bases rondes de même taille.','Le côté relie les deux bases comme celui d’un cylindre.','Un cylindre.'),q('Quel solide ressemble à la balle pleine ?','Cherche la forme toute ronde.','La balle pleine est ronde dans toutes les directions.','Une boule.'),q('La balle pleine possède-t-elle une face plane ?','Une face plane est plate.','La surface de la balle est courbe partout.','Non.'),q('La boîte de conserve possède-t-elle des bases planes ?','Observe son dessus et son dessous.','Les deux bases rondes sont plates.','Oui, deux bases en forme de disque.'),q('Pourquoi ne faut-il pas les appeler toutes les deux des boules ?','Observe les surfaces de chaque solide.','Le cylindre a deux bases planes ; la boule n’en a pas.','Parce que leurs surfaces et leurs formes sont différentes.')]))
S.append(E('Ce que le dessin cache','Une image montre seulement trois faces d’un pavé droit.',[
 q('Combien de faces possède le pavé réel ?','Pense à la boîte entière, pas seulement à la vue.','Un pavé a toujours six faces.','6 faces.'),q('Combien de faces voit-on sur l’image annoncée ?','Lis le nombre donné.','L’image montre trois faces.','3 faces.'),C('Combien de faces sont cachées ?','Retire celles que l’on voit du total.','6-3',3,'faces'),q('Ces faces cachées existent-elles sur l’objet réel ?','Un dessin ne supprime pas une partie du solide.','Elles se trouvent derrière ou dessous et deviennent visibles quand on tourne l’objet.','Oui.'),q('Comment vérifier en manipulant une boîte ?','Tourne-la en marquant ce qui est déjà compté.','Observe chaque côté et compte toutes les faces une fois.','En tournant la boîte pour voir les six faces.')]))
S.append(E('Reproduire un assemblage de trois cubes','Le modèle comporte deux cubes côte à côte et un troisième posé sur celui de gauche.\n\n[IMAGE_1]',[
 q('Combien de cubes faut-il préparer ?','Compte tous les cubes du modèle, en haut et en bas.','$2+1=3$.','3 cubes.'),q('Comment disposes-tu les deux premiers ?','Ils forment la base de l’assemblage.','Pose-les côte à côte, avec leurs faces en contact.','Deux cubes côte à côte.'),q('Où places-tu le troisième ?','La consigne distingue la gauche et la droite du modèle.','Il est au-dessus du cube de gauche, face contre face.','Sur le cube de gauche.'),q('Qu’est-ce qui ne conviendrait pas si tu le plaçais à droite ?','Compare la position avec le modèle.','La colonne de deux cubes ne serait pas du même côté.','L’assemblage serait différent du modèle.'),q('Comment fais-tu vérifier par un camarade ?','Compare les positions, pas seulement le nombre de cubes.','Il vérifie deux cubes en bas et un au-dessus du cube de gauche, vus du même côté que le modèle.','En comparant les trois positions dans la même orientation.')],{'1':'assemblage_trois_cubes.png'}))
