P=[]
P.append(E('Avancer puis tourner','Le pion part du repère D et regarde vers le haut du plan. Sur une copie, suis : avance de 2 cases, tourne à droite, avance de 1 case.\n\n[IMAGE_1]',[
 q('Quelle direction suit le premier déplacement ?','Le pion avance dans la direction où il regarde.','Son regard est vers le haut.','Vers le haut.'),q('De combien de cases avance-t-il d’abord ?','Lis la première instruction.','Il avance de deux cases avant de tourner.','2 cases.'),q('Change-t-il de case en tournant à droite ?','Une rotation se fait sur place.','Il change de direction, mais garde la même case.','Non.'),q('Quelle direction suit le dernier déplacement ?','Après avoir regardé en haut, tourner à droite oriente vers la droite du plan.','Le pion avance alors d’une case vers la droite.','Vers la droite du plan.'),q('Où arrive-t-il par rapport au départ ?','Réunis les déplacements sans compter la rotation comme une case.','Deux cases vers le haut, puis une vers la droite.','2 cases au-dessus et 1 à droite du départ.\n\n[IMAGE_2]')],{'1':'plan_depart.png','2':'trajet_2_1_corrige.png'}))
P.append(E('Dessiner un plan de l’école','Dessine un plan simple de ton école et place trois lieux que tu connais. Si tu n’es pas à l’école, utilise trois lieux d’un espace familier.',[
 q('Depuis quel point de vue représente-t-on les lieux sur un plan ?','Imagine une vue depuis le dessus.','Le plan montre la place des lieux vus de haut.','Vus de dessus.'),q('Quels trois lieux peux-tu choisir ?','Prends des lieux que tu connais réellement.','Par exemple la classe, la cour et la cantine.','Par exemple la classe, la cour et la cantine.'),q('Comment indiques-tu ce que représente chaque zone ?','Un lecteur doit reconnaître les lieux.','Écris le nom de chaque lieu à l’intérieur ou à côté de sa zone.','Avec leur nom ou une légende.'),q('Comment vérifies-tu leurs positions relatives ?','Compare le plan à ce que tu connais de l’espace.','Les lieux qui sont voisins doivent le rester ; la gauche et la droite doivent être cohérentes avec le point de vue choisi.','En comparant les voisinages et les directions.'),q('Pourquoi n’a-t-on pas besoin de dessiner tous les petits détails ?','Un plan sert d’abord à se repérer.','Les lieux utiles et leurs positions suffisent à guider le lecteur.','Pour garder un plan simple et lisible.')]))
P.append(E('Près ou loin de la porte','Observe une pièce et choisis la porte comme repère.',[
 q('Que dois-tu préciser pour dire « près » ou « loin » ?','Ces mots se comprennent par rapport à un repère.','Ici, le repère choisi est la porte.','Le repère : la porte.'),q('Décris un objet près de la porte.','Choisis un objet réellement proche dans la pièce.','Par exemple une chaise placée juste à côté de l’entrée, si c’est le cas.','Réponse selon la pièce : un objet proche de la porte, nommé précisément.'),q('Décris un objet loin de la porte.','Observe un endroit plus éloigné.','Par exemple une table au fond de la pièce, si elle est éloignée de la porte.','Réponse selon la pièce : un objet éloigné de la porte, nommé précisément.'),q('Comment ton camarade peut-il vérifier ?','Il doit utiliser le même repère.','Il regarde les deux objets depuis la porte ou compare leurs distances à la porte.','En utilisant la même porte comme repère.'),q('Un objet peut-il être près d’un mur et loin de la porte ?','Les deux repères ne sont pas forcément au même endroit.','Un objet peut toucher le mur du fond tout en étant éloigné de l’entrée.','Oui, cela dépend du repère.')]))
P.append(E('La droite du pion','Le pion regarde vers la droite du plan. Il tourne à droite puis avance d’une case.',[
 q('Où regarde le pion au départ ?','Lis l’orientation donnée avant d’agir.','Il ne regarde pas vers le haut mais vers la droite.','Vers la droite du plan.'),q('Où regarde-t-il après un quart de tour à droite ?','Imagine le mouvement du pion, pas celui de ton propre regard.','De la droite du plan, tourner à droite conduit vers le bas.','Vers le bas du plan.'),q('A-t-il déjà changé de case en tournant ?','Tourner est une action sur place.','Aucun déplacement n’a encore été demandé.','Non.'),q('Où va-t-il en avançant d’une case ?','Avance dans sa nouvelle direction.','Le pion regarde maintenant vers le bas.','Une case vers le bas.'),q('Où regarderait-il s’il avait tourné à gauche au départ ?','Repars de l’orientation initiale vers la droite.','Un quart de tour à gauche conduit vers le haut.','Vers le haut du plan.')]))
P.append(E('Un trajet en trois déplacements','Le pion regarde vers le haut. Il avance de 2 cases, tourne à droite, avance de 3, tourne à droite et avance de 2.',[
 q('Où se trouve-t-il après le premier déplacement ?','Il avance dans sa direction initiale.','Il part vers le haut et avance de deux cases.','2 cases au-dessus du départ.'),q('Quelle direction suit le deuxième déplacement ?','Le premier virage est à droite depuis le haut.','Le pion regarde maintenant vers la droite du plan.','Vers la droite.'),q('Quelle direction suit le dernier déplacement ?','Le second virage est à droite depuis la droite du plan.','Il regarde alors vers le bas.','Vers le bas.'),q('À quelle ligne arrive-t-il par rapport au départ ?','Deux cases vers le haut puis deux vers le bas se compensent.','Le déplacement vertical total est nul.','Sur la même ligne que le départ.'),q('Donne la position finale et la direction du regard.','Garde le déplacement horizontal et le dernier virage.','Trois cases vers la droite ont été parcourues ; le dernier déplacement était vers le bas.','3 cases à droite du départ, en regardant vers le bas.')]))
P.append(E('Coder un trajet lisible','Sur un plan de l’école ou d’un lieu familier, code un trajet d’au plus dix instructions et trois virages. Fais-le suivre par un camarade.',[
 q('Que précises-tu avant la première instruction ?','Un trajet a besoin d’un départ et d’une orientation.','Sans ces repères, le lecteur pourrait partir d’ailleurs ou regarder dans une autre direction.','Le départ et la direction du regard.'),q('Quelle instruction sert à changer de direction sans avancer ?','Une rotation se fait sur place.','On peut écrire « tourne d’un quart de tour à droite » ou « à gauche ».','Une instruction de rotation à droite ou à gauche.'),q('Quelle instruction sert à changer de case ?','Un déplacement précise une longueur.','Écris par exemple « avance de deux cases ».','Une instruction pour avancer avec le nombre de cases.'),q('Comment contrôles-tu les limites de la consigne ?','Compte séparément toutes les instructions et les virages.','Il doit y avoir au plus dix instructions, dont au plus trois qui font tourner le pion.','Au plus 10 instructions et 3 virages.'),q('Comment vérifies-tu ton programme ?','Un autre lecteur doit pouvoir l’exécuter sans deviner.','Ton camarade suit les instructions une par une et compare l’arrivée avec celle que tu prévoyais.','En faisant suivre le trajet depuis les mêmes repères.')]))
P.append(E('Revenir au départ','Le pion regarde vers le haut. Il avance de 1, tourne à droite, avance de 2, tourne à droite, avance de 1, tourne à droite, avance de 2 et tourne encore à droite.',[
 q('Quelles directions suivent les deux premiers déplacements ?','Suis l’orientation après le premier virage.','D’abord vers le haut, puis vers la droite.','1 case vers le haut, puis 2 vers la droite.'),q('Quelles directions suivent les deux derniers déplacements ?','Continue les deux virages suivants.','La droite après la droite mène vers le bas, puis vers la gauche.','1 case vers le bas, puis 2 vers la gauche.'),q('Où arrive le pion ?','Les déplacements opposés de même longueur se compensent.','Une case vers le haut est compensée par une vers le bas, et deux vers la droite par deux vers la gauche.','Au point de départ.'),q('Où regarde-t-il après le dernier virage ?','Quatre quarts de tour font un tour complet.','Haut, droite, bas, gauche, puis haut.','Vers le haut du plan.'),q('Combien y a-t-il de virages et de déplacements ?','Compte les rotations et les avancées séparément.','Le programme alterne quatre avancées et quatre rotations.','4 virages et 4 déplacements.')]))
P.append(E('Retrouver des lieux sur deux supports','Avec un adulte, compare un plan de l’école ou du quartier et une photographie vue du dessus.',[
 q('Quels lieux peux-tu chercher d’abord ?','Choisis des repères familiers faciles à reconnaître.','Par exemple l’école, la mairie ou la cour.','Deux lieux connus, par exemple l’école et sa cour.'),q('Pourquoi peuvent-ils paraître différents ?','Les supports ne montrent pas tous les détails de la même façon.','Le plan simplifie ; la photographie montre les toits et les objets réels.','Parce que le plan simplifie la photographie.'),q('Comment rapproches-tu les deux orientations ?','Utilise les mêmes lieux comme repères.','Tourne les supports pour que le même trajet aille dans la même direction sur les deux.','En alignant les mêmes repères et les mêmes directions.'),q('Que compares-tu pour vérifier les lieux ?','Observe les voisinages, pas seulement les couleurs.','Cherche la position de la cour près de l’école ou le tracé des rues autour.','Leurs positions et leurs voisins.'),q('Comment expliques-tu ta correspondance à un camarade ?','Nomme les lieux et ce qui les entoure.','Montre un lieu sur le plan puis le même sur la photographie en indiquant un repère commun.','En montrant les mêmes lieux avec un repère commun.')]))
P.append(E('Tourner ou se déplacer','Noé pense que « tourne à droite » veut dire « déplace-toi d’une case vers la droite du dessin ».',[
 q('Est-ce que tourner fait changer de case ?','Distingue rotation et déplacement.','Un pion peut tourner sans avancer.','Non.'),q('Qu’est-ce qui change quand le pion tourne ?','Observe la direction de son regard.','Il regarde dans une autre direction.','Son orientation.'),q('Que faut-il connaître pour comprendre sa droite ?','La droite dépend de la direction initiale.','Il faut savoir où il regarde avant de tourner.','Sa direction de départ.'),q('S’il regarde vers la gauche et tourne à droite, où regarde-t-il ?','Fais un quart de tour depuis la gauche du plan.','La droite du pion dans cette position conduit vers le haut.','Vers le haut du plan.'),q('Quelle phrase corrige l’idée de Noé ?','Précise ce que fait chaque action.','Tourner change la direction sur place ; avancer déplace le pion selon sa direction.','Tourner à droite change le regard, sans déplacer le pion.')]))
emit(30,P)
